<script lang="ts">import {onMount} from 'svelte';import {homeLabels} from '$lib/series/home-i18n';import type {Language} from '$lib/series/i18n';let {lang='ko'}:{lang?:Language}=$props();let ui=$derived(homeLabels[lang]);let ready=$state(false);onMount(()=>{ready=true;});let selected=$state<'previous'|'next'|null>(null);</script>
<section class="focus-demo" lang={lang} aria-labelledby="focus-demo-title"><h2 id="focus-demo-title">{ui.demoTitle}</h2><p>{ui.demoText}</p><p class="keyboard-note"><kbd>Tab</kbd> {ui.move} · <kbd>Enter</kbd> {ui.activate}</p><div class="demo-buttons" data-ready={ready}><button type="button" onclick={()=>selected='previous'}>{ui.previous}</button><button type="button" onclick={()=>selected='next'}>{ui.next}</button></div><p class="demo-status" role="status">{selected==='previous'?ui.selectedPrevious:selected==='next'?ui.selectedNext:ui.idle}</p></section>
